PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX ref: <https://example.org/ref#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?s WHERE {
  ?s rdfs:label "Perimeter_top_ZN_2" .
}

PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX ref: <https://example.org/ref#>
SELECT ?point ?ts ?label WHERE {
  ?point brick:hasParameter brick:Occupancy ;
         brick:isPointOf ?zone ;
         ref:hasTimeseriesId ?ts .
  ?zone rdfs:label "Perimeter_top_ZN_2" .
  ?point rdfs:label ?label .
}

PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?p ?p ?class ?label ?o WHERE {
  ?zone rdfs:label "Perimeter_top_ZN_2" .
  ?p ?o ?zone .
}

PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?z ?label WHERE {
  ?z a brick:Zone ; rdfs:label ?label .
}
